class EditorOps(_Area):
    """The editor itself: what it is and how it is doing (describe), console variables and commands, the idle frame cap of an offscreen editor, waiting for shader/asset compilation to finish, and garbage collection."""
    _area = 'editor'

    def console(self, *, command: str, _wait: bool = True, _timeout: float = 900) -> dict:
        """Run one console command in the editor (stat, r.*, Fab.Login, ...). It cannot report the command's own output:
        read the log (film-ue log) or a cvar after it. Never run Fab.Logout or Fab.SetEnvironment: both delete the
        saved Epic sign-in.

        Args: command: the command line as typed in the console.
        Returns: {"command", "ran": true}.
        Example: film-ue op editor.console 'command=stat unit'

        Args:
            command (str, required)

        Op: editor.console  (unreal/fmbridge/ops/editor.py:114)  mutates=True  idempotent=False  tags=['platform']
        Returns: dict
        """
        return self._call('editor.console', {'command': command}, _wait, _timeout)

    def cvar(self, *, name: str, value: Any = UNSET, _wait: bool = True, _timeout: float = 900) -> dict:
        """Read a console variable, or set it (through the console, as typed there) and read it back.

        Args: name: e.g. "r.RayTracing". value: the new value (number, bool or string); omit to only read.
        Returns: {"name", "value": the value now (string), "before", "changed": bool}.
        Example: film-ue op editor.cvar name=t.MaxFPS value=30

        Args:
            name (str, required)
            value (any, default null)

        Op: editor.cvar  (unreal/fmbridge/ops/editor.py:92)  mutates=True  idempotent=True  tags=['platform']
        Returns: dict
        """
        return self._call('editor.cvar', {'name': name, 'value': value}, _wait, _timeout)

    def describe(self, *, _wait: bool = True, _timeout: float = 900) -> dict:
        """What the editor is and how it is doing: engine, platform, RHI, project, open level, unsaved packages, idle cap,
        shader workers, memory, bridge jobs.

        Returns: {"engine", "platform", "python", "rhi", "project", "level", "dirty": {"maps", "content"},
        "idle_fps", "max_fps", "shader_workers", "rss_mb", "jobs": {"queued", "running"}, "uptime_s"}.
        Example: film-ue op editor.describe


        Op: editor.describe  (unreal/fmbridge/ops/editor.py:73)  mutates=False  idempotent=True  tags=['platform']
        Returns: dict
        """
        return self._call('editor.describe', {}, _wait, _timeout)

    def gc(self, *, _wait: bool = True, _timeout: float = 900) -> dict:
        """Collect garbage (frees unreferenced objects after big imports or level changes) and report memory.

        Returns: {"rss_mb_before", "rss_mb_after"} (Linux; None elsewhere).
        Example: film-ue op editor.gc


        Op: editor.gc  (unreal/fmbridge/ops/editor.py:185)  mutates=False  idempotent=True  tags=['platform']
        Returns: dict
        """
        return self._call('editor.gc', {}, _wait, _timeout)

    def idle(self, *, fps: int = UNSET, realtime: bool = UNSET, _wait: bool = True, _timeout: float = 900) -> dict:
        """Cap an offscreen editor between jobs so it does not hold the GPU at full load: the frame rate (t.MaxFPS) and
        whether the level viewport redraws every frame. Movie Render Queue lifts the cap while it renders (render.mrq).

        Args: fps: the cap (0 = none). realtime: the level viewport in realtime.
        Returns: {"fps", "realtime", "changed"}.
        Example: film-ue op editor.idle fps=10

        Args:
            fps (int, default 30)
            realtime (bool, default false)

        Op: editor.idle  (unreal/fmbridge/ops/editor.py:135)  mutates=True  idempotent=True  tags=['platform']
        Returns: dict
        """
        return self._call('editor.idle', {'fps': fps, 'realtime': realtime}, _wait, _timeout)

    def wait_compile(self, *, timeout_s: float = UNSET, settle_s: float = UNSET, finish: bool = UNSET, _wait: bool = True, _timeout: float = 900) -> Any:
        """Wait until the editor has no shader compiling (no ShaderCompileWorker for `settle_s` seconds), ticking all the
        while, then (finish) let the engine finish any asset compilation left. The first open of a project on a new box
        compiles for many minutes: run this before stills or renders.

        Args: timeout_s: give up after this long (an error with code "timeout"). settle_s: how long the workers must
        stay at zero. finish: then call the engine's finish-all-compilation (blocks briefly).
        Returns: {"waited_s", "workers_max", "finished": bool}. Multi-tick (reports progress).
        Example: film-ue op editor.wait_compile timeout_s=3600

        Args:
            timeout_s (float, default 3600)
            settle_s (float, default 6)
            finish (bool, default true)

        Op: editor.wait_compile  (unreal/fmbridge/ops/editor.py:152)  multi-tick  mutates=False  idempotent=True  tags=['platform', 'slow']
        """
        return self._call('editor.wait_compile', {'timeout_s': timeout_s, 'settle_s': settle_s, 'finish': finish}, _wait, _timeout)


class EnvOps(_Area):
    """Environments: sun and moon by time of day and place, physical sky (atmosphere, volumetric clouds, sky light), HDRI skies, height and volumetric fog, exposure (manual by EV100, physical camera, auto), colour grading, Lumen/VSM/HWRT quality, """
